<section class="section live-results section-scroll-target" id="compliance-results" data-section-target aria-live="polite" aria-busy="false">
    <div class="section-heading"><h2>Student compliance</h2><span class="muted">Showing <?= e($compliancePagination['from']) ?>–<?= e($compliancePagination['to']) ?> of <?= e($compliancePagination['total']) ?> students</span></div>
    <div class="table-wrap"><table data-no-datatable><thead><tr><th>Student</th><th>Section</th><th>Absences</th><th>Tardies</th><th>Tardy equivalent</th><th>Missed events</th><th>Missed recollections</th><th>Total</th><?php if ($canIssueViolations): ?><th class="compliance-row-actions">Actions</th><?php endif; ?></tr></thead><tbody>
    <?php foreach ($compliance as $row): ?><tr><td><a href="<?= e(url('/admin/?page=profile&id=' . $row['id'])) ?>" class="entity-user-trigger" data-entity-user data-user-id="<?= e($row['id']) ?>" data-user-name="<?= e($row['student_name']) ?>" data-user-school-id="<?= e($row['school_id']) ?>" data-user-role="Student"><strong><?= e($row['student_name']) ?></strong></a><br><span class="muted"><?= e($row['school_id']) ?></span></td><td><?= e($row['section_name']) ?></td><td><?= e($row['absences']) ?></td><td><?= e($row['tardies']) ?></td><td><?= e($row['tardy_equivalent']) ?></td><td><?= e($row['missed_events']) ?></td><td><?= e($row['missed_recollections']) ?></td><td><strong class="compliance-total"><?= e($row['total_deficiencies']) ?></strong></td><?php if ($canIssueViolations): ?><td class="compliance-row-actions"><button type="button" class="icon-action-button violation-action" data-issue-violation data-student-id="<?= e($row['id']) ?>" data-student-name="<?= e($row['student_name']) ?>" data-student-school-id="<?= e($row['school_id']) ?>" title="Issue violation" aria-label="Issue violation to <?= e($row['student_name']) ?>"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 2.5 18 17H2L10 2.5Z"/><path d="M10 7v4.5M10 14.5h.01"/></svg></button></td><?php endif; ?></tr><?php endforeach; ?>
    <?php if (!$compliance): ?><tr><td colspan="<?= $canIssueViolations ? '9' : '8' ?>" class="empty-state">No students match the current search and filters.</td></tr><?php endif; ?>
    </tbody></table></div>
    <?php if ($compliancePagination['pages'] > 1): ?><nav class="server-pagination" aria-label="Compliance result pages"><?php for ($pageNumber = 1; $pageNumber <= $compliancePagination['pages']; $pageNumber++): ?><?php $query = array_filter(['page' => 'compliance', 'q' => $_GET['q'] ?? '', 'program_id' => $_GET['program_id'] ?? '', 'section_id' => $_GET['section_id'] ?? '', 'compliance_page' => $pageNumber], static fn($value): bool => $value !== '' && $value !== 0); ?><a class="<?= $pageNumber === $compliancePagination['page'] ? 'is-active' : '' ?>" href="<?= e(url('/admin/?' . http_build_query($query))) ?>" data-live-page="<?= e($pageNumber) ?>" <?= $pageNumber === $compliancePagination['page'] ? 'aria-current="page"' : '' ?>><?= e($pageNumber) ?></a><?php endfor; ?></nav><?php endif; ?>
